/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_logisticsPostalAddress">_logisticsPostalAddress</param>
protected void initFromLogisticsPostalAddress(LogisticsPostalAddress _logisticsPostalAddress)
{
    next initFromLogisticsPostalAddress(_logisticsPostalAddress);
    this.NDXLogisticsLocationName1  = _logisticsPostalAddress.NDXLogisticsLocationName1;
    this.NDXLogisticsLocationName2  = _logisticsPostalAddress.NDXLogisticsLocationName2;
    this.NDXLogisticsLocationName3  = _logisticsPostalAddress.NDXLogisticsLocationName3;
}

/// <summary>
