protected void initFromEDIAddress(AVAEDIAddress _ediAddress)
{
    next initFromEDIAddress(_ediAddress);
    this.NDXLogisticsLocationName1  = _ediAddress.NDXLogisticsLocationName1;
    this.NDXLogisticsLocationName2  = _ediAddress.NDXLogisticsLocationName2;
